prompts.user:
/ [셋업] POS별 문항 풀에서 랜덤 인덱스(*_IDX) 추출
@SET(N_IDX, "@INDEX("@N@", "@N[.]@")@", SELF)@
@SET(V_IDX, "@INDEX("@V@", "@V[.]@")@", SELF)@
@SET(ADJ_IDX, "@INDEX("@ADJ@", "@ADJ[.]@")@", SELF)@
@SET(OTH_IDX, "@INDEX("@OTH@", "@OTH[.]@")@", SELF)@

// [채점] 학생 응답 정오 판정 후 점수·correctness 기록 (EXACT: 정확 일치)

1. Noun
T/F boolean: @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@

Current Score: @JSON_test_config.Result[1].Noun@

Enumerated: @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@

update:
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@)@
@UPJ(JSON_test_config.Noun[@R_i@].Student_answer, "@TEXT(P_N@R_i@)@")@
@UPJ(JSON_test_config.Noun[@R_i@].correctness, @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@)@

2. Verb
T/F boolean: @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",EXACT)@

Current Score: @JSON_test_config.Result[1].Verb@

Enumerated: @EVAL("@JSON_test_config.Result[1].Verb@ + @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",EXACT)@")@

update:
@UPJ(JSON_test_config.Result[1].Verb, @EVAL("@JSON_test_config.Result[1].Verb@ + @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",EXACT)@")@)@
@UPJ(JSON_test_config.Verb[@R_i@].Student_answer, "@TEXT(P_V@R_i@)@")@
@UPJ(JSON_test_config.Verb[@R_i@].correctness, @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",EXACT)@)@

3. Adjective
T/F boolean: @MAP("@TEXT(P_ADJ@R_i@)@", "@JSON_test_config.Adjective[@R_i@].answer@", "1|0",EXACT)@

Current Score: @JSON_test_config.Result[1].Adjective@

Enumerated: @EVAL("@JSON_test_config.Result[1].Adjective@ + @MAP("@TEXT(P_ADJ@R_i@)@", "@JSON_test_config.Adjective[@R_i@].answer@", "1|0",EXACT)@")@

update:
@UPJ(JSON_test_config.Result[1].Adjective, @EVAL("@JSON_test_config.Result[1].Adjective@ + @MAP("@TEXT(P_ADJ@R_i@)@", "@JSON_test_config.Adjective[@R_i@].answer@", "1|0",EXACT)@")@)@
@UPJ(JSON_test_config.Adjective[@R_i@].Student_answer, "@TEXT(P_ADJ@R_i@)@")@
@UPJ(JSON_test_config.Adjective[@R_i@].correctness, @MAP("@TEXT(P_ADJ@R_i@)@", "@JSON_test_config.Adjective[@R_i@].answer@", "1|0",EXACT)@)@

4. Others
T/F boolean: @MAP("@TEXT(P_OTH@R_i@)@", "@JSON_test_config.others[@R_i@].answer@", "1|0",EXACT)@

Current Score: @JSON_test_config.Result[1].others@

Enumerated: @EVAL("@JSON_test_config.Result[1].others@ + @MAP("@TEXT(P_OTH@R_i@)@", "@JSON_test_config.others[@R_i@].answer@", "1|0",EXACT)@")@

update:
@UPJ(JSON_test_config.Result[1].others, @EVAL("@JSON_test_config.Result[1].others@ + @MAP("@TEXT(P_OTH@R_i@)@", "@JSON_test_config.others[@R_i@].answer@", "1|0",EXACT)@")@)@
@UPJ(JSON_test_config.others[@R_i@].Student_answer, "@TEXT(P_OTH@R_i@)@")@
@UPJ(JSON_test_config.others[@R_i@].correctness, @MAP("@TEXT(P_OTH@R_i@)@", "@JSON_test_config.others[@R_i@].answer@", "1|0",EXACT)@)@

// [집계] 인덱싱 보정(-1) 후 POS 점수 누적 합산(Cumulative)
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ - 1")@)@
@UPJ(JSON_test_config.Result[1].Verb, @EVAL("@JSON_test_config.Result[1].Verb@ - 1")@)@
@UPJ(JSON_test_config.Result[1].Adjective, @EVAL("@JSON_test_config.Result[1].Adjective@ - 1")@)@
@UPJ(JSON_test_config.Result[1].others, @EVAL("@JSON_test_config.Result[1].others@ - 1")@)@

@UPJ(JSON_test_config.Result[1].Cumulative, @EVAL("@JSON_test_config.Result[1].Noun@+@JSON_test_config.Result[1].Verb@+@JSON_test_config.Result[1].Adjective@+@JSON_test_config.Result[1].others@")@)@
